class Solution {
    fun largestTimeFromDigits(arr:IntArray):String{
        var best=-1;
        for(i in 0..3)for(j in 0..3)if(j!=i)for(k in 0..3)if(k!=i&&k!=j)for(l in 0..3)if(l!=i&&l!=j&&l!=k){
